function b64urlToBytes(s){
  s = String(s).replace(/-/g,'+').replace(/_/g,'/');
  while(s.length % 4) s += '=';
  try {
    var bin = (typeof atob !== 'undefined') ? atob(s) : Buffer.from(s,'base64').toString('binary');
    var bytes = []; for(var i=0;i<bin.length;i++) bytes.push(bin.charCodeAt(i) & 0xff);
    return bytes;
  } catch(e){ return null; }
}
function utf8FromBytes(bytes){
  var s=''; var i=0;
  while(i<bytes.length){
    var c=bytes[i++];
    if(c<0x80) s+=String.fromCharCode(c);
    else if(c>=0xC0 && c<0xE0) s+=String.fromCharCode(((c&0x1F)<<6)|(bytes[i++]&0x3F));
    else s+=String.fromCharCode(((c&0x0F)<<12)|((bytes[i++]&0x3F)<<6)|(bytes[i++]&0x3F));
  }
  return s;
}
function b64urlDecode(s){ var b=b64urlToBytes(s); if(b===null) return null; return utf8FromBytes(b); }
function bytesToB64url(bytes){
  var bin=''; for(var i=0;i<bytes.length;i++) bin+=String.fromCharCode(bytes[i]);
  var b = (typeof btoa !== 'undefined') ? btoa(bin) : Buffer.from(bin,'binary').toString('base64');
  return b.replace(/\+/g,'-').replace(/\//g,'_').replace(/=+$/,'');
}
function b64urlEncode(str){
  var bytes=[];
  for(var i=0;i<str.length;i++){
    var c=str.charCodeAt(i);
    if(c<0x80) bytes.push(c);
    else if(c<0x800) bytes.push(0xC0|(c>>6), 0x80|(c&0x3F));
    else bytes.push(0xE0|(c>>11), 0x80|((c>>6)&0x3F), 0x80|(c&0x3F));
  }
  return bytesToB64url(bytes);
}
function decode(token){
  if(typeof token !== 'string' || !token.trim()) return {error:'JWT 为空'};
  var parts = token.trim().split('.');
  if(parts.length !== 3) return {error:'JWT 需要 3 段（header.payload.signature）'};
  try {
    var h = b64urlDecode(parts[0]); var p = b64urlDecode(parts[1]);
    if(h === null || p === null) return {error:'Base64URL 解码失败'};
    var header = JSON.parse(h); var payload = JSON.parse(p);
    return {header:header, payload:payload, signature:parts[2], error:null};
  } catch(e){ return {error:'JSON 解析失败：'+e.message}; }
}
function pad(n){ return (n<10?'0':'')+n; }
function fmtDate(sec){
  var d = new Date(sec*1000);
  if(isNaN(d.getTime())) return '无效时间';
  return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())+' '+pad(d.getHours())+':'+pad(d.getMinutes())+':'+pad(d.getSeconds());
}
function humanize(payload){
  var out = {};
  for(var k in payload){ if(payload.hasOwnProperty(k)) out[k]=payload[k]; }
  var now = Date.now()/1000;
  ['exp','iat','nbf'].forEach(function(f){
    if(typeof payload[f] === 'number'){
      out['_'+f+'_human'] = fmtDate(payload[f]);
      if(f === 'exp') out['_expired'] = payload[f] < now;
      if(f === 'iat') out['_iat_ago'] = payload[f] <= now ? Math.floor(now-payload[f]) + ' 秒前' : '未来';
      if(f === 'nbf') out['_nbf_active'] = payload[f] <= now;
    }
  });
  return out;
}
function analyze(token, nowSec){
  var d = decode(token);
  if(d.error) return {valid:false, error:d.error};
  var now = (typeof nowSec === 'number') ? nowSec : Date.now()/1000;
  var exp = (typeof d.payload.exp === 'number') ? d.payload.exp : null;
  var nbf = (typeof d.payload.nbf === 'number') ? d.payload.nbf : null;
  var algNone = d.header.alg === 'none';
  var expired = exp !== null && exp < now;
  var notYet = nbf !== null && nbf > now;
  return {valid:true, header:d.header, payload:d.payload, signature:d.signature, algNone:algNone, expired:expired, notYet:notYet};
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { b64urlDecode:b64urlDecode, b64urlEncode:b64urlEncode, decode:decode, humanize:humanize, analyze:analyze, fmtDate:fmtDate };
}
if (typeof window !== 'undefined') {
  window.JwtForgePure = { b64urlDecode:b64urlDecode, b64urlEncode:b64urlEncode, decode:decode, humanize:humanize, analyze:analyze };
}
